    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// </summary>
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        ref float start = ref MemoryMarshal.GetReference(values);
        int length = values.Length;

        if (Vector512.IsHardwareAccelerated && length >= Vector512<float>.Count)
            return FindMinMax512(ref start, length);

        if (Vector256.IsHardwareAccelerated && length >= Vector256<float>.Count)
            return FindMinMax256(ref start, length);

        if (Vector128.IsHardwareAccelerated && length >= Vector128<float>.Count)
            return FindMinMax128(ref start, length);

        return FindMinMaxScalar(ref start, length);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static (float Min, float Max) FindMinMax512(ref float start, int length)
    {
        const int stride = 16; // Vector512<float>.Count
        ref float ptr = ref start;

        var vMin = Vector512.LoadUnsafe(ref ptr);
        var vMax = vMin;
        int i = stride;

        // Process two vectors per iteration to improve ILP
        int limit = length - stride * 2 + 1;
        for (; i < limit; i += stride * 2)
        {
            var v0 = Vector512.LoadUnsafe(ref ptr, (nuint)i);
            var v1 = Vector512.LoadUnsafe(ref ptr, (nuint)(i + stride));
            vMin = Vector512.Min(vMin, Vector512.Min(v0, v1));
            vMax = Vector512.Max(vMax, Vector512.Max(v0, v1));
        }

        for (; i <= length - stride; i += stride)
        {
            var v = Vector512.LoadUnsafe(ref ptr, (nuint)i);
            vMin = Vector512.Min(vMin, v);
            vMax = Vector512.Max(vMax, v);
        }

