        var minHi = vMin.GetUpper();
        var maxLo = vMax.GetLower();
        var maxHi = vMax.GetUpper();
        var min256 = Vector256.Min(minLo, minHi);
        var max256 = Vector256.Max(maxLo, maxHi);
        var min128 = Vector128.Min(min256.GetLower(), min256.GetUpper());
        var max128 = Vector128.Max(max256.GetLower(), max256.GetUpper());
